// band mod ("Jauge"): Julian's always-visible live gauge, read-only.
// Above the prompt: this conversation's context against auto-compact and the RESUME hand-off threshold, the burn rate
// at the scopes the settings list, and the week's rate-limit use. /jauge opens the pane: per-scope table, hottest
// sessions, projects, 30-minute sparklines with compaction markers, and each conversation's compactions.
// Line 1 also carries « À toi : N » and « attend Julian : N » once each, counted by lib/core/veille.mjs in the scanner.
// Under the band, a Mods button bar (launcher in band.config.json, preset hubs: Jauge, Cockpit, Veille, À toi,
// Registres, Référence): a press runs the other mod's slash command, which opens that mod's own pane ($.ui.open draws
// only the caller's panes, so a mod cannot open another's directly); a second press runs /<command> close. Jauge is
// band's own pane, opened directly. A mod whose command is not in the session is greyed out and says how to load it.
// Sources: $.session.usage() / session.measure for this conversation (the status line's figures), and
// scanner/scan.mjs, an incremental tail of ~/.claude/projects/**/*.jsonl run every refresh_s. Nothing here blocks or
// rewrites a tool call or a prompt.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { EngineFigures } from '../types'
import {
  SCOPES,
  bandParts,
  bandText,
  compactLabel,
  contextInfo,
  deepMerge,
  expandHome,
  fmtPct,
  fmtTok,
  fmtUsd,
  ageText,
  handoffAdvice,
  handoffButtons,
  handoffReason,
  hhmm,
  allLauncherItems,
  launcherButtons,
  launcherItems,
  othersOpen,
  launcherPress,
  launcherKey,
  launcherTyped,
  markerLine,
  recentHandoffs,
  resumeCandidates,
  sparkline,
  toggleOpen,
} from './logic'
import type { BandPart, Config, Ctx, HandoffButton, LauncherButton, View } from './logic'
import { gaugeModel, gaugeSvg, gaugeText } from './gauge'
import { fitButtons, fitLine, jaugeCfg } from './jauge'
import type { Field, JaugeCfg, JaugeFacts } from './jauge'
import type { Gauge } from './gauge'
import {
  sectionsCfg,
  sectionList,
  initialUi,
  toggleSection,
  isOpen,
  headLine,
  convSummary,
  convLines,
  counters,
} from './sections'
import type { BandUi, SectionsCfg } from './sections'

// The gauge's input from this conversation's context and the band's rates (style "gauge", the default).
const gaugeOf = (c: Config, ctx: Ctx | undefined, v: View | null, week: number | undefined): Gauge => {
  const lb = c.labels
  const rates: string[] = []
  for (const id of ((c as any).gauge?.scopes as string[] | undefined) ?? c.band.scopes) {
    const row = v?.scopes.find(r => r.id === id)
    if (!row) continue
    const r = row.rates.find(x => x.w === c.band_window_s) ?? row.rates[0]
    if (r) rates.push(`${lb[id] ?? id} ${fmtTok(r.tps)} tok/s`)
  }
  const idle = ctx?.idleEtaMin !== undefined && (ctx.idleMin ?? 0) >= c.idle_compact.show_after_idle_min ? ctx.idleEtaMin : undefined
  return gaugeModel(
    {
      tokens: ctx?.tokens,
      window: ctx?.window ?? c.context.window_fallback,
      compactAt: ctx?.threshold,
      handoffAt: c.context.handoff_tokens,
      etaMin: ctx?.etaMin ?? idle,
      level: ctx?.level,
      rates,
      ...(week !== undefined ? { week } : {}),
    },
    (c as any).gauge?.labels ?? {},
  )
}

// The two-line Jauge's figures: counters from the scanner (lib/core/veille.mjs), context from the engine, Claude's
// 5 h / week from the engine's rate limits (else the usage mod's samples), Codex's from its codex.json, PC activity,
// tok/s of the scopes in jauge.tps_scopes, CPU / GPU from the scanner.
const jaugeFacts = (c: Config, jc: JaugeCfg, ctx: Ctx | undefined, v: View | null, en: EngineFigures | null): JaugeFacts => {
  const lim = (k: string) => en?.limits?.find(l => l.kind === k && Number.isFinite(l.percentUsed))?.percentUsed
  const tps: Record<string, number | undefined> = {}
  for (const [id, scope] of Object.entries(jc.tps_scopes)) {
    const row = v?.scopes.find(r => r.id === scope)
    const r = row ? (row.rates.find(x => x.w === c.band_window_s) ?? row.rates[0]) : undefined
    tps[id] = r?.tps
  }
  const pct = ctx?.tokens !== undefined && ctx.window ? (ctx.tokens * 100) / ctx.window : undefined
  return {
    waiting: v?.waiting?.julian,
    todo: v?.waiting?.aToi,
    ctxPct: pct,
    relayAt: c.context.handoff_tokens,
    five: lim('five_hour') ?? v?.claude?.five,
    week: lim('seven_day') ?? en?.week ?? v?.claude?.week,
    codexWeek: v?.codex?.week,
    codexFive: v?.codex?.five,
    agents: v?.pc?.agents,
    convs: v?.pc?.convs,
    tps,
    cpu: v?.machine?.cpu,
    gpu: v?.machine?.gpu,
  }
}

const PANE = { id: 'jauge' }
const viewAtom = atom({ plugin: 'band', key: 'view' } as const, null)
const engineAtom = atom({ plugin: 'band', key: 'engine' } as const, null)
const errorAtom = atom({ plugin: 'band', key: 'error' } as const, '')
const launcherAtom = atom({ plugin: 'band', key: 'launcher' } as const, { commands: [], open: [] })
const handoffAtom = atom({ plugin: 'band', key: 'handoff' } as const, { ran: [], show: false })
const uiAtom = atom({ plugin: 'band', key: 'ui' } as const, { expanded: false, open: [] })
const STORE_KEY = 'sections'

const secCfg = (c: Config): SectionsCfg => sectionsCfg((c as any).sections)

// The folding at session start: $.store's (remember "store"), else the config's defaults. A reload keeps $.state's.
const loadUi = async ($: EngineInterface, c: Config) => {
  const sc = secCfg(c)
  let stored: unknown
  if (sc.remember === 'store') {
    try {
      stored = await $.store.get(STORE_KEY)
    } catch {}
  }
  const ui = initialUi(sc, stored)
  await update($, uiAtom, () => ui)
}

const toggleUi = async ($: EngineInterface, id: string) => {
  const c = await loadConfig($)
  const next = await update($, uiAtom, u => toggleSection(u as BandUi, id))
  if (secCfg(c).remember === 'store') {
    try {
      await $.store.set(STORE_KEY, next)
    } catch {}
  }
}

type Options = { config?: string; band?: string; status_line?: string }

const DOCS = {
  statusline: 'https://code.claude.com/docs/en/statusline',
  mods: 'https://code.claude.com/docs/en/plugins/mods/overview',
}

const home = async ($: EngineInterface) => {
  let v: string | undefined
  try {
    v = await $.env.get('USERPROFILE')
  } catch {}
  if (!v) {
    try {
      v = await $.env.get('HOME')
    } catch {}
  }
  return v ?? ''
}

let options: Options = {}
let cfg: Config | undefined
let cfgProblem = ''
let scanning = false
let thresholdAt = 0
let threshold: number | undefined
let timer: { cancel: () => void } | undefined

const loadConfig = async ($: EngineInterface): Promise<Config> => {
  if (cfg) return cfg
  const root = $.plugin.root.replace(/\\/g, '/')
  let base = {} as Config
  try {
    base = JSON.parse((await $.fs.read(`${root}/band.config.json`, { as: 'text' })) as string)
  } catch (err) {
    cfgProblem = `band.config.json: ${String(err).slice(0, 120)}`
  }
  if (options.config?.trim()) {
    const p = expandHome(options.config.trim(), await home($))
    try {
      base = deepMerge(base, JSON.parse((await $.fs.read(p, { as: 'text' })) as string))
    } catch (err) {
      cfgProblem = `${p}: ${String(err).slice(0, 120)}`
    }
  }
  cfg = base
  return base
}

let sessionFacts: { model?: string; effort?: string; at: number } = { at: 0 }

const figures = async ($: EngineInterface, context?: { tokens?: number; window: number; percent?: number }, limits?: { kind: string; percentUsed: number; resetsAt?: string }[]) => {
  const now = await $.clock.now()
  let cost: number | undefined
  if (!context || !limits) {
    try {
      const u = await $.session.usage()
      context = u.context
      limits = u.rateLimits
      cost = (u as any).cost?.usd
    } catch {}
  } else {
    const prev = await read($, engineAtom)
    cost = prev?.cost
  }
  // model and effort: cheap, local, once a minute
  if (now - sessionFacts.at > 60000) {
    sessionFacts = { at: now }
    try {
      sessionFacts.model = await $.session.model()
    } catch {}
    try {
      sessionFacts.effort = (await $.env.get('CLAUDE_EFFORT')) || undefined
    } catch {}
  }
  // The auto-compact threshold is only in the breakdown; "summary" counts locally and sends nothing. Every 5 min.
  if (now - thresholdAt > 300000) {
    thresholdAt = now
    try {
      const u = await $.session.usage({ breakdown: 'summary' })
      threshold = u.context.breakdown?.isAutoCompactEnabled === false ? undefined : u.context.breakdown?.autoCompactThreshold
    } catch {}
  }
  const week = limits?.find(l => l.kind === 'seven_day')?.percentUsed
  const f: EngineFigures = {
    ...(context?.tokens !== undefined ? { tokens: context.tokens } : {}),
    ...(context?.window ? { window: context.window } : {}),
    ...(context?.percent !== undefined ? { percent: context.percent } : {}),
    ...(threshold !== undefined ? { autoCompactThreshold: threshold } : {}),
    ...(week !== undefined ? { week } : {}),
    ...(limits ? { limits: limits.map(l => ({ kind: l.kind, percentUsed: l.percentUsed, ...(l.resetsAt ? { resetsAt: l.resetsAt } : {}) })) } : {}),
    ...(cost !== undefined && Number.isFinite(cost) ? { cost } : {}),
    ...(sessionFacts.model ? { model: sessionFacts.model } : {}),
    ...(sessionFacts.effort ? { effort: sessionFacts.effort } : {}),
    at: now,
  }
  await update($, engineAtom, () => f)
}

const ctxOf = (c: Config, e: EngineFigures | null, v: View | null, now: number): Ctx | undefined => {
  if (!e && !v?.conv) return undefined
  return contextInfo(
    {
      tokens: e?.tokens ?? v?.conv?.ctx,
      window: e?.window,
      percent: e?.percent,
      autoCompactThreshold: e?.autoCompactThreshold,
      growthTpm: v?.conv?.growthTpm,
      last: v?.conv?.last,
      now,
    },
    c.context,
    c.idle_compact,
  )
}

const statusLine = async ($: EngineInterface) => {
  const c = await loadConfig($)
  if (options.status_line !== 'on') return
  const v = await read($, viewAtom)
  const e = await read($, engineAtom)
  const ctx = ctxOf(c, e, v, await $.clock.now())
  $.ui.status(bandText(bandParts(v ?? undefined, ctx, e?.week, c.status_line, c)) || undefined)
}

// The slash commands of this session, to grey out the mods that are not loaded. Local: no model call.
const seeCommands = async ($: EngineInterface) => {
  try {
    const list = await $.command.list()
    const commands = list.map(c => ({ name: c.name, ...(c.plugin ? { plugin: c.plugin } : {}) }))
    await update($, launcherAtom, l => ({ ...l, commands }))
  } catch {}
}

const buttonsOf = async ($: EngineInterface, c: Config) => {
  const l = await read($, launcherAtom)
  return launcherButtons(c.launcher, l.commands, l.open, c.labels)
}

// The unfolded buttons (more_items: Jauge), same rules as the hubs.
const moreButtonsOf = async ($: EngineInterface, c: Config) => {
  const l = await read($, launcherAtom)
  const more = c.launcher?.more_items
  return Array.isArray(more) && more.length ? launcherButtons({ ...c.launcher, preset: 'hubs', items: more }, l.commands, l.open, c.labels) : []
}

// launcher.single: one hub open at a time. Opening `key` closes every other hub known open (not those of the same
// command, which the opening run replaces anyway): /<command> <close_args>, or band's own Jauge pane directly.
// fromHook: called inside a command.run hook, where the engine refuses $.command.run (it would wait on the turn the
// hook holds), so the closing runs go to a timer ($.clock.after 0).
const closeOthers = async ($: EngineInterface, c: Config, key: string, command: string, fromHook = false) => {
  if (!c.launcher?.single) return
  const l = await read($, launcherAtom)
  const others = othersOpen(allLauncherItems(c.launcher), l.open, key).filter(o => o.command !== command)
  if (!others.length) return
  const shut = others.map(launcherKey)
  await update($, launcherAtom, x => ({ ...x, open: x.open.filter(k => !shut.includes(k)) }))
  const closeArgs = c.launcher?.close_args || 'close'
  const runs: { command: string; args: string }[] = []
  for (const o of others) {
    if (o.mod === 'band' && o.command === 'jauge') {
      await $.ui.close({ id: PANE.id })
      continue
    }
    if (!runs.some(r => r.command === o.command)) runs.push({ command: o.command, args: closeArgs })
  }
  const go = () => {
    for (const r of runs) $.command.run(r).catch((err: unknown) => $.ui.toast(`/${r.command} ${r.args} : ${String(err).slice(0, 160)}`))
  }
  if (!runs.length) return
  if (fromHook) $.clock.after(0, go)
  else go()
}

// A press: open the mod (/<command>) or close it (/<command> close). $.command.run queues the command until the
// session is idle, so it is not awaited here; while Claude works a toast says it is queued.
const press = async ($: EngineInterface, b: LauncherButton, isWorking: boolean) => {
  const c = await loadConfig($)
  const a = launcherPress(b, c.launcher?.close_args || 'close')
  if ('toast' in a) {
    $.ui.toast(a.toast)
    return
  }
  if (a.open) await closeOthers($, c, launcherKey(b), b.command)
  await update($, launcherAtom, l => ({ ...l, open: toggleOpen(l.open, launcherKey(b), a.open) }))
  // Jauge is band's own pane: $.command.run skips the caller's own hooks, so open or close it here.
  if (b.mod === 'band' && b.command === 'jauge') {
    if (a.open) {
      await $.ui.open({ id: PANE.id, title: c.labels.pane_title ?? 'Jauge' })
      void refresh($)
    } else await $.ui.close({ id: PANE.id })
    return
  }
  if (isWorking) $.ui.toast(`${b.label} : ${c.labels.launcher_queued ?? 'queued'}`)
  $.command.run(a.run).catch(async (err: unknown) => {
    await update($, launcherAtom, l => ({ ...l, open: toggleOpen(l.open, launcherKey(b), !a.open) }))
    $.ui.toast(`/${b.command} : ${String(err).slice(0, 160)}`)
  })
}

// ---------- hand-off helper ----------
// Read-only: it stats RESUME and reads it on a press; « Préparer RESUME » runs the handoff command only on a press.

const seeResume = async ($: EngineInterface, c: Config) => {
  const hc = c.handoff
  if (!hc || hc.enabled === false) return
  let cwd = ''
  try {
    cwd = await $.session.cwd()
  } catch {}
  const places = resumeCandidates(cwd, hc.files ?? [], c.worktree_markers)
  let resume: { path: string; mtime?: number } | undefined = places[0] ? { path: places[0] } : undefined
  for (const p of places) {
    try {
      const st = await $.fs.stat(p)
      if (st.kind === 'file') {
        resume = { path: p, mtime: st.mtimeMs }
        break
      }
    } catch {}
  }
  let startedAt: number | undefined
  try {
    startedAt = (await $.session.usage()).startedAt
  } catch {}
  await update($, handoffAtom, s => ({ ...s, resume, ...(startedAt !== undefined ? { startedAt } : {}) }))
}

const noteRan = async ($: EngineInterface) => {
  const now = await $.clock.now()
  await update($, handoffAtom, s => ({ ...s, ran: [...s.ran, now].slice(-10) }))
}

const showResume = async ($: EngineInterface, c: Config) => {
  await seeResume($, c)
  const s = await read($, handoffAtom)
  let text: string | undefined
  if (s.resume?.mtime !== undefined) {
    try {
      const all = (await $.fs.read(s.resume.path, { as: 'text' })) as string
      const cap = c.handoff?.preview_chars ?? 12000
      text = all.length > cap ? `${all.slice(0, cap)}\n\n…` : all
    } catch {}
  } else $.ui.toast(`RESUME ${c.labels.handoff_absent ?? 'absent'} : ${s.resume?.path ?? '?'}`)
  await update($, handoffAtom, x => ({ ...x, show: true, ...(text !== undefined ? { text } : {}) }))
  await $.ui.open({ id: PANE.id, title: c.labels.pane_title ?? 'Jauge' })
}

const pressHandoff = async ($: EngineInterface, b: HandoffButton, isWorking: boolean) => {
  const c = await loadConfig($)
  const hc = c.handoff
  if (!hc) return
  if (!b.enabled) {
    $.ui.toast(b.hint ?? b.label)
    return
  }
  if (b.key === 'handoff-open') {
    await showResume($, c)
    return
  }
  if (isWorking) $.ui.toast(`${b.label} : ${c.labels.handoff_queued ?? 'queued'}`)
  // $.command.run skips the calling plugin's own hooks, so band's command.run observer will not see this run: note it here.
  await noteRan($)
  $.command
    .run({ command: hc.command, ...(hc.args ? { args: hc.args } : {}) })
    .catch((err: unknown) => $.ui.toast(`/${hc.command} : ${String(err).slice(0, 160)}`))
}

const fileHref = (p: string) => `file:///${encodeURI(p.replace(/\\/g, '/').replace(/^\/+/, ''))}`

const refresh = async ($: EngineInterface) => {
  if (scanning) return
  scanning = true
  try {
    const c = await loadConfig($)
    const h = await home($)
    const root = $.plugin.root.replace(/\\/g, '/')
    let session = ''
    let cwd = ''
    try {
      session = await $.session.id()
      cwd = await $.session.cwd()
    } catch {}
    const req = {
      projects_root: expandHome(c.projects_root, h),
      cache_file: expandHome(c.cache_file, h),
      session,
      cwd,
      now: await $.clock.now(),
      cfg: c,
    }
    const r = await $.process.run([c.node, `${root}/scanner/scan.mjs`], { stdin: JSON.stringify(req), timeoutMs: 180000 })
    let parsed: any
    try {
      parsed = JSON.parse(r.stdout)
    } catch {
      parsed = { error: (r.stderr || r.stdout || `exit ${r.exitCode}`).slice(0, 300) }
    }
    if (parsed?.error) await update($, errorAtom, () => String(parsed.error).split('\n')[0])
    else {
      await update($, viewAtom, () => parsed as View)
      await update($, errorAtom, () => '')
    }
    await figures($)
    await statusLine($)
    await seeCommands($)
    await seeResume($, c)
  } catch (err) {
    await update($, errorAtom, () => `scanner: ${String(err).slice(0, 200)}`)
  } finally {
    scanning = false
  }
}

export const register: Register = (on, raw) => {
  options = (raw ?? {}) as Options
  cfg = undefined
  timer?.cancel()
  timer = undefined

  on('session.start', async ($, e, next) => {
    const started = await next(e)
    await $.command.register({
      name: 'jauge',
      description: 'Jauge: contexte de cette conversation, débit en tok/s par périmètre, sessions les plus actives, compactages (args: [refresh])',
      argumentHint: '[refresh]',
    })
    const c = await loadConfig($)
    await loadUi($, c)
    timer?.cancel()
    timer = $.clock.every(Math.max(5, c.refresh_s) * 1000, () => void refresh($))
    void seeCommands($)
    void refresh($)
    return started
  })

  // Observe only: a launcher mod's command typed by the person keeps the button's open state in step. Passes through.
  on('command.run', async ($, e, next) => {
    const r = await next(e)
    try {
      const c = await loadConfig($)
      if (c.handoff && c.handoff.enabled !== false && e.command === c.handoff.command) await noteRan($)
      const t = launcherTyped(allLauncherItems(c.launcher), e.command, e.args ?? '', c.launcher?.close_args || 'close')
      if (t) {
        for (const k of t.open) await closeOthers($, c, k, e.command, true)
        await update($, launcherAtom, l => ({ ...l, open: [...l.open.filter(k => !t.close.includes(k)), ...t.open.filter(k => !l.open.includes(k))] }))
      }
    } catch {}
    return r
  }).catch(($, e, next) => next(e))

  // The Jauge pane closed by its own ✕: the Jauge button follows. Passes through.
  on('ui.close', { id: PANE.id }, async ($, e, next) => {
    await update($, launcherAtom, l => ({ ...l, open: l.open.filter(k => k !== 'band') }))
    return next(e)
  }).catch(($, e, next) => next(e))

  on('session.measure', async ($, e, next) => {
    const r = await next(e)
    await figures($, e.context, e.rateLimits as { kind: string; percentUsed: number }[])
    await statusLine($)
    return r
  }).catch(($, e, next) => next(e))

  on('command.run', { command: 'jauge' }, async ($, e) => {
    const c = await loadConfig($)
    if ((e.args ?? '').trim() === (c.launcher?.close_args || 'close')) {
      await $.ui.close({ id: PANE.id })
      return { text: 'jauge: fermée' }
    }
    await refresh($)
    await $.ui.open({ id: PANE.id, title: c.labels.pane_title ?? 'Jauge' })
    const v = await read($, viewAtom)
    const en = await read($, engineAtom)
    const err = await read($, errorAtom)
    const ctx = ctxOf(c, en, v, await $.clock.now())
    const text = bandText(bandParts(v ?? undefined, ctx, en?.week, { items: c.band.items, scopes: [...SCOPES] }, c))
    let relay = ''
    if (c.handoff && c.handoff.enabled !== false) {
      const hs = await read($, handoffAtom)
      const advice = handoffAdvice(ctx, c.handoff)
      relay = ` · passation : ${advice.show ? `${c.labels.handoff_advice ?? 'conseillée'} (${handoffReason(advice, ctx, c.handoff, c.labels)})` : 'pas encore'} · RESUME ${ageText(hs.resume?.mtime, await $.clock.now(), c.labels)}`
    }
    return { text: `jauge: ${text || 'pas encore de mesure'}${relay}${err ? ` · erreur: ${err}` : ''}${cfgProblem ? ` · ${cfgProblem}` : ''}` }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (options.band === 'off' || e.props.hasSurvey) return next(e)
    const c = await loadConfig($)
    const v = await read($, viewAtom)
    const en = await read($, engineAtom)
    const ctx = ctxOf(c, en, v, v?.now ?? Date.now())
    const parts = bandParts(v ?? undefined, ctx, en?.week, c.band, c)
    const buttons = await buttonsOf($, c)
    const advice = c.handoff?.band === false ? { show: false, reasons: [] } : handoffAdvice(ctx, c.handoff)
    // What the mods after this one draw (veille's line, machine's entry) stays, below the gauge and the Mods bar.
    const theirs = await next(e)
    if (!parts.length && !buttons.length && !advice.show) return theirs
    const els = $.ui.resolve(e)
    const { Box, Text, Button } = els
    const Svg = e.surface === 'terminal' ? undefined : (els as any).Svg
    const color = (p: BandPart) => (p.tone ? c.colors[p.tone] : undefined)
    const isWorking = e.props.isWorking
    const style = (c as any).gauge?.style ?? 'two_lines'
    if (style === 'two_lines') {
      const jc = jaugeCfg((c as any).jauge)
      const ui = (await read($, uiAtom)) as BandUi
      const cols = Math.max(20, Number((e.props as any).bodyColumns) || jc.columns_fallback)
      const facts = jaugeFacts(c, jc, ctx, v ?? null, en)
      const l1 = fitLine(jc.line1, facts, jc, cols)
      const l2 = fitLine(jc.line2, facts, jc, cols)
      const toneOf = (f: Field) => (f.tone === 'bad' ? { color: c.colors.bad ?? 'error' } : f.tone === 'dim' ? { dimColor: true } : {})
      const segs: { key: string; text: string; field?: Field }[] = []
      l1.line.forEach((g, gi) => {
        if (gi) segs.push({ key: `j1-sep${gi}`, text: l1.sep })
        g.forEach((f, fi) => {
          if (fi) segs.push({ key: `j1-dot${gi}-${fi}`, text: l1.dot })
          segs.push({ key: `j1-${f.id}`, text: f.text, field: f })
        })
      })
      const line1 = (
        <Box key="jauge-l1" flexDirection="row" flexWrap="nowrap">
          {segs.map(x => (
            <Text key={x.key} bold {...(x.field ? toneOf(x.field) : { dimColor: true })} wrap="truncate-end">
              {x.text}
            </Text>
          ))}
        </Box>
      )
      const line2 = l2.text ? (
        <Box key="jauge-l2" flexDirection="row" flexWrap="nowrap">
          <Text key="jauge-l2-t" dimColor wrap="truncate-end">{l2.text}</Text>
        </Box>
      ) : null
      const fitted = fitButtons(buttons.map(b => ({ label: b.label, ...(b.short ? { short: b.short } : {}), open: b.open })), jc, cols, 1)
      const toggleLabel = ui.expanded ? (jc.labels.less ?? '▴') : (jc.labels.more ?? '▾')
      const row = (
        <Box key="jauge-buttons" flexDirection="row" flexWrap="nowrap" gap={1}>
          {buttons.map((b, i) => (
            <Button
              key={`mod-${launcherKey(b)}`}
              {...(b.loaded ? {} : { dimColor: true })}
              {...(b.open ? { variant: 'primary' as const } : {})}
              onPress={() => press($, b, isWorking)}
            >
              {fitted.labels[i]}
            </Button>
          ))}
          <Button key="band-toggle" onPress={() => toggleUi($, 'band')}>
            {toggleLabel}
          </Button>
        </Box>
      )
      let relayJ = null
      if (advice.show && c.handoff) {
        const hs = await read($, handoffAtom)
        const lc = await read($, launcherAtom)
        const hb = handoffButtons(c.handoff, lc.commands, hs.resume, c.labels)
        relayJ = (
          <Box key="band-relay" flexDirection="row" flexWrap="nowrap" gap={1}>
            <Text color={c.colors.warn} wrap="truncate-end">{`${c.labels.handoff_advice ?? 'Passation conseillée'} : ${handoffReason(advice, ctx, c.handoff, c.labels)}`}</Text>
            {hb.map(b => (
              <Button key={b.key} {...(b.enabled ? {} : { dimColor: true })} onPress={() => pressHandoff($, b, isWorking)}>
                {b.label}
              </Button>
            ))}
          </Box>
        )
      }
      let more = null
      if (ui.expanded) {
        const sc = secCfg(c)
        const L = sc.labels
        const mb = await moreButtonsOf($, c)
        const cf = { model: en?.model, effort: en?.effort, agents: v?.conv?.agents, pr: v?.conv?.pr, tokens: ctx?.tokens, handoffAt: c.context.handoff_tokens }
        const hasConv = sectionList(sc).includes('conv')
        const convOpen = hasConv && isOpen(ui, 'conv')
        more = (
          <Box key="jauge-more" flexDirection="column">
            <Box key="jauge-more-row" flexDirection="row" flexWrap="nowrap" gap={1}>
              {mb.map(b => (
                <Button
                  key={`mod-${launcherKey(b)}`}
                  {...(b.loaded ? {} : { dimColor: true })}
                  {...(b.open ? { variant: 'primary' as const } : {})}
                  onPress={() => press($, b, isWorking)}
                >
                  {b.open ? `${b.label} ✕` : b.label}
                </Button>
              ))}
              {hasConv ? (
                <Button key="sec-conv" onPress={() => toggleUi($, 'conv')}>
                  {`${convOpen ? '▾' : '▸'} ${L.conv}`}
                </Button>
              ) : null}
              {hasConv && !convOpen ? <Text dimColor wrap="truncate-end">{convSummary(cf, L)}</Text> : null}
            </Box>
            {convOpen ? (
              <Box flexDirection="column" marginLeft={2}>
                {convLines(cf, L).map((t, i) => (
                  <Text key={`cl${i}`} dimColor={i > 0} wrap="truncate-end">{t}</Text>
                ))}
              </Box>
            ) : null}
          </Box>
        )
      }
      return (
        <Box flexDirection="column">
          {line1}
          {line2}
          {relayJ}
          {row}
          {more}
          {theirs ?? null}
        </Box>
      )
    }
    if (style === 'compact') {
      const sc = secCfg(c)
      const L = sc.labels
      const ui = (await read($, uiAtom)) as BandUi
      const g = gaugeOf(c, ctx, v ?? null, undefined)
      const gw = (c as any).gauge?.width ?? 120
      const scope = (((c as any).gauge?.scopes as string[] | undefined) ?? ['conv'])[0]
      const srow = v?.scopes.find(r => r.id === scope)
      const rate = srow ? (srow.rates.find(x => x.w === c.band_window_s) ?? srow.rates[0]) : undefined
      const compactions = v?.compactions.find(r => r.isThis)?.items.length
      const head = headLine({ ctxPct: g.pct, etaMin: ctx?.etaMin, tps: rate?.tps, compactions, limits: en?.limits }, L)
      const tone = c.colors[g.level]
      const marks = g.marks.map(m => m.label).join(' · ')
      const line1 = (
        <Box key="band-line" flexDirection="row" gap={1} alignItems="center" flexWrap="nowrap">
          {Svg && g.hasReading ? (
            <Svg key="band-gauge" source={gaugeSvg(g, (c as any).gauge?.colors ?? {}, gw, (c as any).gauge?.mark_labels ?? 'nearest')} alt={`${g.title} · ${marks}`} />
          ) : (
            <Text key="band-gauge-t" color={tone}>{gaugeText(g, (c as any).gauge?.text_width ?? 12)}</Text>
          )}
          <Text key="band-head" color={tone} wrap="truncate-end">{head}</Text>
          {counters(v?.waiting, L).map(k => (
            <Text key={k.key} bold color={c.colors.bad ?? '#f85149'}>{k.text}</Text>
          ))}
          <Button key="band-toggle" onPress={() => toggleUi($, 'band')}>
            {ui.expanded ? '▾' : '▸'}
          </Button>
        </Box>
      )
      const facts = {
        model: en?.model,
        effort: en?.effort,
        agents: v?.conv?.agents,
        pr: v?.conv?.pr,
        tokens: ctx?.tokens,
        handoffAt: c.context.handoff_tokens,
      }
      const header = (id: string, title: string, summary: string) => (
        <Box key={`sec-h-${id}`} flexDirection="row" gap={1} alignItems="center" flexWrap="nowrap">
          <Button key={`sec-${id}`} onPress={() => toggleUi($, id)}>
            {`${isOpen(ui, id) ? '▾' : '▸'} ${title}`}
          </Button>
          {isOpen(ui, id) ? null : <Text dimColor wrap="truncate-end">{summary}</Text>}
        </Box>
      )
      const sections = sectionList(sc).map(id => {
        if (id === 'mods') return null
        if (!ui.expanded) return null
        if (id === 'conv') {
          return (
            <Box key="sec-conv" flexDirection="column">
              {header('conv', L.conv, convSummary(facts, L))}
              {isOpen(ui, 'conv') ? (
                <Box flexDirection="column" marginLeft={2}>
                  {convLines(facts, L).map((t, i) => (
                    <Text key={`cl${i}`} dimColor={i > 0}>{t}</Text>
                  ))}
                </Box>
              ) : null}
            </Box>
          )
        }
        return null
      })
      let relayC = null
      if (advice.show && c.handoff) {
        const hs = await read($, handoffAtom)
        const lc = await read($, launcherAtom)
        const hb = handoffButtons(c.handoff, lc.commands, hs.resume, c.labels)
        relayC = (
          <Box key="band-relay" flexDirection="row" flexWrap="wrap" gap={1}>
            <Text color={c.colors.warn}>{`${c.labels.handoff_advice ?? 'Passation conseillée'} : ${handoffReason(advice, ctx, c.handoff, c.labels)}`}</Text>
            {hb.map(b => (
              <Button key={b.key} {...(b.enabled ? {} : { dimColor: true })} onPress={() => pressHandoff($, b, isWorking)}>
                {b.label}
              </Button>
            ))}
            <Text dimColor>{`RESUME ${ageText(hs.resume?.mtime, v?.now ?? Date.now(), c.labels)}`}</Text>
          </Box>
        )
      }
      const allButtons = [...buttons, ...(await moreButtonsOf($, c))]
      const modsRow =
        sectionList(sc).includes('mods') && allButtons.length ? (
          <Box key="band-mods" flexDirection="row" flexWrap="wrap" gap={1}>
            <Text dimColor>{`${c.labels.launcher ?? 'Mods'} :`}</Text>
            {allButtons.map(b => (
              <Button
                key={`mod-${launcherKey(b)}`}
                {...(b.loaded ? {} : { dimColor: true })}
                {...(b.open ? { variant: 'primary' as const } : {})}
                onPress={() => press($, b, isWorking)}
              >
                {b.open ? `${b.label} ✕` : b.loaded ? b.label : `${b.label} · ${b.hint ?? ''}`}
              </Button>
            ))}
          </Box>
        ) : null
      const order = sectionList(sc)
      const body = order.map((id, i) => (id === 'mods' ? modsRow : sections[i]))
      return (
        <Box flexDirection="column">
          {line1}
          {relayC}
          {body}
          {theirs ?? null}
        </Box>
      )
    }
    const gaugeStyle = style === 'gauge'
    const g = gaugeStyle ? gaugeOf(c, ctx, v ?? null, en?.week) : undefined
    const gaugeEl = g ? (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1} alignItems="center" flexWrap="wrap">
          <Text color={c.colors[g.level]}>{g.title}</Text>
          {Svg ? null : <Text color={c.colors[g.level]}>{gaugeText(g, (c as any).gauge?.text_width ?? 30)}</Text>}
        </Box>
        {Svg && g.hasReading ? <Svg source={gaugeSvg(g, (c as any).gauge?.colors ?? {}, (c as any).gauge?.width ?? 320)} alt={`${g.title}${g.marks.map(m => ' · ' + m.label).join('')}`} /> : null}
        {g.line ? <Text dimColor>{g.line}</Text> : null}
      </Box>
    ) : null
    let relay = null
    if (advice.show && c.handoff) {
      const hs = await read($, handoffAtom)
      const lc = await read($, launcherAtom)
      const hb = handoffButtons(c.handoff, lc.commands, hs.resume, c.labels)
      relay = (
        <Box flexDirection="row" flexWrap="wrap" gap={1}>
          <Text color={c.colors.warn}>{`${c.labels.handoff_advice ?? 'Passation conseillée'} : ${handoffReason(advice, ctx, c.handoff, c.labels)}`}</Text>
          {hb.map(b => (
            <Button key={b.key} {...(b.enabled ? {} : { dimColor: true })} onPress={() => pressHandoff($, b, isWorking)}>
              {b.label}
            </Button>
          ))}
          <Text dimColor>{`RESUME ${ageText(hs.resume?.mtime, v?.now ?? Date.now(), c.labels)}`}</Text>
        </Box>
      )
    }
    return (
      <Box flexDirection="column">
        {gaugeEl}
        {!gaugeStyle && parts.length ? (
          <Box flexDirection="row" flexWrap="wrap">
            {parts.map((p, i) => (
              <Text key={`b${i}`} {...(color(p) ? { color: color(p) } : { dimColor: true })}>
                {`${i ? ' · ' : ''}${p.text}`}
              </Text>
            ))}
          </Box>
        ) : null}
        {relay}
        {buttons.length ? (
          <Box flexDirection="row" flexWrap="wrap" gap={1}>
            <Text dimColor>{`${c.labels.launcher ?? 'Mods'} :`}</Text>
            {buttons.map(b => (
              <Button
                key={`mod-${launcherKey(b)}`}
                {...(b.loaded ? {} : { dimColor: true })}
                {...(b.open ? { variant: 'primary' as const } : {})}
                onPress={() => press($, b, isWorking)}
              >
                {b.open ? `${b.label} ✕` : b.loaded ? b.label : `${b.label} · ${b.hint ?? ''}`}
              </Button>
            ))}
          </Box>
        ) : null}
        {theirs ?? null}
      </Box>
    )
  }).catch(($, e, next) => next(e))

  on('ui.render', { component: 'Pane', requestId: 'jauge' }, async ($, e) => {
    const { Box, Text, Button, Link, Markdown } = $.ui.resolve(e)
    const c = await loadConfig($)
    const v = await read($, viewAtom)
    const en = await read($, engineAtom)
    const err = await read($, errorAtom)
    const now = v?.now ?? Date.now()
    const ctx = ctxOf(c, en, v, now)
    const lb = c.labels
    const tone = (t?: string) => (t && c.colors[t] ? { color: c.colors[t] } : {})
    const pad = (s: string, n: number) => (s.length >= n ? s.slice(0, n) : s + ' '.repeat(n - s.length))
    const lpad = (s: string, n: number) => (s.length >= n ? s : ' '.repeat(n - s.length) + s)
    const nv = <Text color={c.colors.warn}>non vérifié</Text>

    const head = (
      <Box flexDirection="row" gap={1} flexWrap="wrap">
        <Button key="refresh" hotkey="r" onPress={() => refresh($)}>
          Actualiser
        </Button>
        <Text dimColor>
          {v
            ? `mesuré à ${hhmm(v.now)} · ${v.files} fichier(s) lus en ${v.ms} ms · usage et prix: ${v.lib} · compte: ${v.count === 'all' ? 'tout (lectures cache comprises)' : 'entrée + écriture cache + sortie'}`
            : 'pas encore de mesure'}
        </Text>
      </Box>
    )

    const conv = ctx ? (
      <Box flexDirection="column">
        <Text bold>Cette conversation</Text>
        <Text {...tone(ctx.level)}>
          {`contexte ${fmtTok(ctx.tokens ?? 0)} / ${fmtTok(ctx.window)} (${fmtPct(ctx.usedPct ?? 0)})`}
        </Text>
        <Box flexDirection="row" gap={1}>
          <Text>{`seuil d'auto-compact ${fmtTok(ctx.threshold)} (${fmtPct(ctx.thresholdPct)}) · reste ${fmtTok(ctx.toCompact ?? 0)} (${fmtPct(ctx.toCompactPct ?? 0)})`}</Text>
          {ctx.thresholdSource === 'config' ? nv : null}
        </Box>
        <Text>
          {ctx.etaMin !== undefined
            ? `${lb.compact_in} ~${Math.max(1, Math.round(ctx.etaMin))} min au débit actuel (+${fmtTok(v?.conv?.growthTpm ?? 0)} tok/min de contexte)`
            : 'compactage : pas d’estimation (contexte stable sur la fenêtre)'}
        </Text>
        <Text {...tone(ctx.relay === 'over' ? 'bad' : ctx.relay === 'near' ? 'warn' : undefined)}>
          {`relais (RESUME) à ${fmtTok(c.context.handoff_tokens)} : ${ctx.relay === 'over' ? lb.relay_over : ctx.relay === 'near' ? lb.relay_near : `reste ${fmtTok(Math.max(0, c.context.handoff_tokens - (ctx.tokens ?? 0)))}`}`}
        </Text>
        <Box flexDirection="row" gap={1}>
          <Text>
            {ctx.idleEtaMin !== undefined
              ? `${lb.idle_compact_in} ~${Math.round(ctx.idleEtaMin)} min (inactif depuis ${Math.round(ctx.idleMin ?? 0)} min, > ${fmtTok(c.idle_compact.min_tokens)})`
              : `compaction au repos : non (sous ${fmtTok(c.idle_compact.min_tokens)} ou actif)`}
          </Text>
          {nv}
        </Box>
        {en?.week !== undefined ? <Text>{`${lb.week} ${fmtPct(en.week)} (limite 7 jours)`}</Text> : null}
      </Box>
    ) : null

    let relay = null
    const hc = c.handoff
    if (hc && hc.enabled !== false) {
      const hs = await read($, handoffAtom)
      const lc = await read($, launcherAtom)
      const advice = handoffAdvice(ctx, hc)
      const hb = handoffButtons(hc, lc.commands, hs.resume, lb)
      const mine = v?.compactions.find(r => r.isThis)?.items ?? []
      const hist = recentHandoffs(mine, hs.ran, hs.resume, hs.startedAt, hc.history_n, lb, c.idle_compact.idle_min)
      relay = (
        <Box flexDirection="column">
          <Text bold>{lb.handoff_title ?? 'Passation (RESUME)'}</Text>
          {advice.show ? (
            <Text color={c.colors.warn}>{`${lb.handoff_advice ?? 'Passation conseillée'} : ${handoffReason(advice, ctx, hc, lb)}`}</Text>
          ) : (
            <Text dimColor>{`pas encore : conseillée à ${fmtTok(hc.threshold_tokens)} de contexte ou si l'auto-compact est prévu dans ${hc.eta_min} min`}</Text>
          )}
          <Box flexDirection="row" flexWrap="wrap" gap={1}>
            {hb.map(b => (
              <Button key={`p-${b.key}`} {...(b.enabled ? {} : { dimColor: true })} onPress={() => pressHandoff($, b, false)}>
                {b.label}
              </Button>
            ))}
            {hs.show ? (
              <Button key="p-handoff-hide" onPress={() => update($, handoffAtom, s => ({ ...s, show: false }))}>
                Masquer RESUME
              </Button>
            ) : null}
          </Box>
          <Text dimColor>{`/${hc.command}${hc.args ? ` ${hc.args}` : ''} · ${hb[0].hint ?? 'se lance seulement sur clic'}`}</Text>
          {hs.resume ? (
            <Box flexDirection="row" flexWrap="wrap" gap={1}>
              <Text>{`${hs.resume.path} : ${ageText(hs.resume.mtime, now, lb)}`}</Text>
              {hs.resume.mtime !== undefined ? <Link href={fileHref(hs.resume.path)} label="ouvrir le fichier" /> : null}
              {hs.resume.mtime !== undefined ? nv : null}
            </Box>
          ) : (
            <Text dimColor>RESUME : dossier de la session inconnu</Text>
          )}
          <Text dimColor>{lb.handoff_history ?? 'Derniers relais et compactages'}</Text>
          {hist.length === 0 ? <Text dimColor>{lb.handoff_none ?? 'aucun'}</Text> : null}
          {hist.map((x, i) => (
            <Text key={`hh-${i}`} {...(x.kind === 'compact' ? {} : { color: c.colors.this })}>{`${hhmm(x.t)}  ${x.text}`}</Text>
          ))}
          {hs.show && hs.text !== undefined ? <Markdown key="resume-md" text={hs.text} /> : null}
        </Box>
      )
    }

    const w = v?.windows ?? c.windows_s
    const wl = (s: number) => (s >= 60 ? `${Math.round(s / 60)} min` : `${s} s`)
    const table = v ? (
      <Box flexDirection="column">
        <Text bold>Débit par périmètre</Text>
        <Text dimColor>{pad('périmètre', 16) + w.map(x => lpad(`tok/s ${wl(x)}`, 16) + lpad('tok/min', 10) + lpad('tok/h', 9) + lpad('$/h', 9)).join('')}</Text>
        {v.scopes.map(row => (
          <Text key={`sc-${row.id}`}>
            {pad(lb[row.id] ?? row.id, 16) +
              row.rates.map(r => lpad(fmtTok(r.tps), 16) + lpad(fmtTok(r.tpm), 10) + lpad(fmtTok(r.tph), 9) + lpad(fmtUsd(r.usdPerH), 9)).join('')}
          </Text>
        ))}
        {v.repo ? <Text dimColor>{`projet = ${v.repo} (worktrees compris)`}</Text> : null}
      </Box>
    ) : null

    const top = v?.top.length ? (
      <Box flexDirection="column">
        <Text bold>{`Sessions les plus actives (${wl(Math.max(...w))})`}</Text>
        <Text dimColor>{pad('session', 34) + pad('projet', 18) + lpad('tok/s', 8) + lpad('$/h', 9) + lpad('ctx', 8) + lpad('compactages', 13)}</Text>
        {v.top.map(t => (
          <Text key={`top-${t.s}`} {...(t.isThis ? { color: c.colors.this } : {})}>
            {pad((t.isThis ? '> ' : '') + t.title, 34) +
              pad(t.repo, 18) +
              lpad(fmtTok(t.tps), 8) +
              lpad(fmtUsd(t.usdPerH), 9) +
              lpad(t.ctx ? fmtTok(t.ctx) : '-', 8) +
              lpad(t.compactions ? `${t.compactions} (${hhmm(t.lastCompact ?? 0)})` : '0', 13)}
          </Text>
        ))}
        {v.projects.length ? (
          <Text dimColor>{'projets : ' + v.projects.slice(0, 5).map(p => `${p.repo} ${fmtTok(p.tps)} tok/s (${p.sessions})`).join(' · ')}</Text>
        ) : null}
      </Box>
    ) : null

    const sparks = v ? (
      <Box flexDirection="column">
        <Text bold>{`Dernières ${v.spark_min} min (une colonne = ${wl(v.bucket_s)}, ▲ = compactage)`}</Text>
        {(['conv', 'project', 'all'] as const)
          .map(id => ({ id, row: v.scopes.find(r => r.id === id) }))
          .filter(x => x.row)
          .map(({ id, row }) => (
            <Box key={`sp-${id}`} flexDirection="column">
              <Text>{`${pad(lb[id] ?? id, 12)}${sparkline(row!.spark)}  max ${fmtTok(Math.max(0, ...row!.spark) / v.bucket_s)} tok/s`}</Text>
              {v.marks[id].length ? <Text color={c.colors.warn}>{pad('', 12) + markerLine(row!.spark.length, v.marks[id])}</Text> : null}
            </Box>
          ))}
      </Box>
    ) : null

    const comps = v ? (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1}>
          <Text bold>{`Compactages (${c.compact_history_hours} h)`}</Text>
          <Text dimColor>entrées system/compact_boundary des transcripts ; « au repos » déduit de l’inactivité avant la compaction :</Text>
          {nv}
        </Box>
        {v.compactions.length === 0 ? <Text dimColor>aucun</Text> : null}
        {v.compactions.slice(0, 10).map(r => (
          <Text key={`cp-${r.s}`} {...(r.isThis ? { color: c.colors.this } : {})}>
            {`${pad((r.isThis ? '> ' : '') + r.title, 34)} ${pad(r.repo, 16)} ${r.items.length} : ` +
              r.items
                .slice(-6)
                .map(x => `${hhmm(x.t)} ${compactLabel(x, lb, c.idle_compact.idle_min)}${x.pre ? ` ${fmtTok(x.pre)}→${fmtTok(x.post ?? 0)}` : ''}`)
                .join(' · ')}
          </Text>
        ))}
      </Box>
    ) : null

    const buttons = [...(await buttonsOf($, c)), ...(await moreButtonsOf($, c))]
    const mods = buttons.length ? (
      <Box flexDirection="column">
        <Text bold>{c.labels.launcher ?? 'Mods'}</Text>
        {buttons.map(b => (
          <Box key={`ml-${launcherKey(b)}`} flexDirection="row" gap={1}>
            <Button key={`mp-${launcherKey(b)}`} {...(b.loaded ? {} : { dimColor: true })} onPress={() => press($, b, false)}>
              {b.open ? `${b.label} ✕` : b.label}
            </Button>
            <Text dimColor>{b.loaded ? `/${b.command}${b.open ? ' · ouvert' : ''}` : (b.hint ?? '')}</Text>
          </Box>
        ))}
      </Box>
    ) : null

    return (
      <Box flexDirection="column" gap={1}>
        {head}
        {mods}
        {err ? <Text color={c.colors.bad}>{`erreur : ${err}`}</Text> : null}
        {cfgProblem ? <Text color={c.colors.bad}>{cfgProblem}</Text> : null}
        {conv}
        {relay}
        {table}
        {top}
        {sparks}
        {comps}
        <Box flexDirection="column">
          <Text dimColor>Sources : contexte et limites = $.session.usage() (les chiffres de la status line) ; débits = transcripts ~/.claude/projects (une ligne par réponse, dédoublonnée par id) ; $ = prix catalogue estimés.</Text>
          <Box flexDirection="row" gap={1}>
            <Link href={DOCS.statusline} label={DOCS.statusline} />
            <Link href={DOCS.mods} label={DOCS.mods} />
          </Box>
        </Box>
      </Box>
    )
  })
}

files.hooks/logic.ts:
// band mod ("Jauge"): the pure math. Rates over sliding windows, scope grouping (worktree -> repo), context and
// compaction figures, sparklines and the French band text. No I/O here: the scanner (scanner/scan.mjs) and the hooks
// module (register.tsx) both import it, and node --test runs it directly (Node 22.18+ strips the types).

import type { Compaction, CompactRow, CountMode, Ev, Rate, ScopeId, ScopeRow, SessionMeta, TopRow, Usage, View } from '../types'

export type { Compaction, CompactRow, CountMode, Ev, Rate, ScopeId, ScopeRow, SessionMeta, TopRow, Usage, View }

/** This conversation's agents in the kept window: total seen, running (wrote within runningS), the running Workflow. */
export const agentsOf = (events: Ev[], session: string | undefined, now: number, runningS: number) => {
  if (!session) return undefined
  const last = new Map<string, { t: number; w?: string }>()
  for (const e of events) {
    if (e.s !== session || !e.a) continue
    const p = last.get(e.a)
    if (!p || e.t > p.t) last.set(e.a, { t: e.t, ...(e.w ? { w: e.w } : {}) })
  }
  const running = [...last.values()].filter(x => now - x.t <= runningS * 1000)
  const wf = running.filter(x => x.w).sort((a, b) => b.t - a.t)[0]?.w
  return { running: running.length, total: last.size, ...(wf ? { workflow: wf } : {}) }
}

/** The whole PC: agents running (subagents and Workflow agents that wrote within runningS) and conversations active
 * (any of their files wrote within activeS), from the kept events. */
export const pcActivity = (events: Ev[], now: number, runningS: number, activeS: number) => {
  const agents = new Set<string>()
  const convs = new Set<string>()
  for (const e of events) {
    if (e.t > now) continue
    if (e.a && now - e.t <= runningS * 1000) agents.add(`${e.s}/${e.a}`)
    if (now - e.t <= activeS * 1000) convs.add(e.s)
  }
  return { agents: agents.size, convs: convs.size }
}


export type Rates = Record<string, { in: number; out: number; cache_read: number; cache_write_5m: number }>

export type Config = {
  projects_root: string
  cache_file: string
  node: string
  refresh_s: number
  windows_s: number[]
  band_window_s: number
  spark_min: number
  bucket_s: number
  top_n: number
  count: CountMode
  compact_history_hours: number
  first_read_mb: number
  shared_lib: string
  worktree_markers: string[]
  band: { items: string[]; scopes: string[] }
  status_line: { items: string[]; scopes: string[] }
  launcher?: Launcher
  handoff?: HandoffCfg
  context: {
    window_fallback: number
    autocompact_pct_fallback: number
    warn_tokens: number
    handoff_tokens: number
    handoff_near_tokens: number
    growth_window_s: number
  }
  idle_compact: { min_tokens: number; idle_min: number; show_after_idle_min: number }
  colors: Record<string, string>
  labels: Record<string, string>
  rates: Rates
}

export const SCOPES = ['conv', 'conv_all', 'agents', 'workflows', 'project', 'all'] as const

// ---------- numbers ----------

export const tokensOf = (u: Usage, mode: CountMode) => u.inp + u.cw + u.out + (mode === 'all' ? u.cr : 0)

const rateFor = (rates: Rates, model: string) => {
  if (rates[model]) return rates[model]
  const m = model.toLowerCase()
  for (const fam of ['fable', 'opus', 'sonnet', 'haiku']) if (m.includes(fam) && rates[fam]) return rates[fam]
  return rates.default ?? { in: 0, out: 0, cache_read: 0, cache_write_5m: 0 }
}

/** List-price dollars of one response (cache writes priced at the 5-minute rate). */
/** A price table, or a function pricing one response (the shared mods/usage price table). */
export type Price = Rates | ((e: Ev) => number)

export const costOf = (e: Ev, rates: Price) => {
  if (typeof rates === 'function') return rates(e)
  const r = rateFor(rates, e.m)
  return (e.u.inp * r.in + e.u.cw * r.cache_write_5m + e.u.cr * r.cache_read + e.u.out * r.out) / 1e6
}

/** French number: 120, 2,1 k, 41 k, 1,2 M. */
export const fmtTok = (n: number) => {
  const a = Math.abs(n)
  const one = (x: number) => (x < 10 ? x.toFixed(1).replace('.', ',').replace(/,0$/, '') : String(Math.round(x)))
  if (a < 1000) return String(Math.round(n))
  if (a < 1e6) return `${one(n / 1000)} k`
  return `${one(n / 1e6)} M`
}
export const fmtUsd = (n: number) => `${n < 10 ? n.toFixed(2) : Math.round(n).toString()} $`.replace('.', ',')
export const fmtPct = (n: number) => `${Math.round(n)} %`
export const hhmm = (t: number) => {
  const d = new Date(t)
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`
}

// ---------- scopes ----------

const norm = (p: string) => p.replace(/\\/g, '/').replace(/\/+$/, '').replace(/^([a-z]):/, (_, d: string) => `${d.toUpperCase()}:`)

/** Repo key of a working directory: a worktree folder (".claude/worktrees/x", ...) counts as its repo. */
export const repoKey = (cwd: string | undefined, markers: string[]) => {
  if (!cwd) return '?'
  let p = norm(cwd)
  for (const m of markers) {
    const i = p.toLowerCase().indexOf(m.toLowerCase())
    if (i > 0) p = p.slice(0, i)
  }
  return p
}
export const repoName = (key: string) => key.split('/').filter(Boolean).pop() ?? key

export type ScopeCtx = { session?: string; repo?: string; repoOf: (s: string) => string | undefined }

export const inScope = (scope: ScopeId, e: Ev, c: ScopeCtx) => {
  switch (scope) {
    case 'conv':
      return e.s === c.session && !e.a
    case 'conv_all':
      return e.s === c.session
    case 'agents':
      return e.s === c.session && !!e.a
    case 'workflows':
      return e.s === c.session && !!e.w
    case 'project':
      return !!c.repo && c.repoOf(e.s) === c.repo
    case 'all':
      return true
  }
}


/** Sliding-window rate: the events with t in (now - w, now], over w seconds. */
export const rateOf = (events: Ev[], now: number, wS: number, mode: CountMode, rates: Price): Rate => {
  const from = now - wS * 1000
  let tokens = 0
  let usd = 0
  let calls = 0
  for (const e of events) {
    if (e.t <= from || e.t > now) continue
    tokens += tokensOf(e.u, mode)
    usd += costOf(e, rates)
    calls++
  }
  const tps = tokens / wS
  return { w: wS, tokens, tps, tpm: tps * 60, tph: tps * 3600, usdPerH: (usd / wS) * 3600, calls }
}

/** Tokens per bucket over the last `minutes`, oldest first. */
export const spark = (events: Ev[], now: number, minutes: number, bucketS: number, mode: CountMode) => {
  const n = Math.max(1, Math.round((minutes * 60) / bucketS))
  const out = new Array<number>(n).fill(0)
  const start = now - n * bucketS * 1000
  for (const e of events) {
    if (e.t <= start || e.t > now) continue
    const i = Math.min(n - 1, Math.floor((e.t - start) / (bucketS * 1000)))
    out[i] += tokensOf(e.u, mode)
  }
  return out
}
export const bucketOf = (t: number, now: number, minutes: number, bucketS: number) => {
  const n = Math.max(1, Math.round((minutes * 60) / bucketS))
  const start = now - n * bucketS * 1000
  if (t <= start || t > now) return -1
  return Math.min(n - 1, Math.floor((t - start) / (bucketS * 1000)))
}
const BARS = '▁▂▃▄▅▆▇█'
export const sparkline = (values: number[]) => {
  const max = Math.max(0, ...values)
  return values.map(v => (v <= 0 ? ' ' : BARS[Math.min(7, Math.floor((v / max) * 7.999))])).join('')
}
export const markerLine = (n: number, marks: number[], ch = '▲') => {
  const a = new Array<string>(n).fill(' ')
  for (const i of marks) if (i >= 0 && i < n) a[i] = ch
  return a.join('')
}

// ---------- the view the scanner hands to the mod ----------


const titleOf = (m: SessionMeta | undefined, s: string) => m?.title || s.slice(0, 8)

/** Context growth of the main thread, tokens per minute, over the last `wS` seconds; none across a compaction. */
export const growthTpm = (samples: [number, number][], now: number, wS: number) => {
  const from = now - wS * 1000
  const xs = samples.filter(([t]) => t > from && t <= now)
  if (xs.length < 2) return undefined
  let k = xs.length - 1
  while (k > 0 && xs[k - 1][1] <= xs[k][1]) k--
  const a = xs[k]
  const b = xs[xs.length - 1]
  if (b[0] <= a[0] || b[1] <= a[1]) return undefined
  return ((b[1] - a[1]) / (b[0] - a[0])) * 60000
}

export const buildView = (
  events: Ev[],
  sessions: Record<string, SessionMeta>,
  cfg: Pick<Config, 'windows_s' | 'spark_min' | 'bucket_s' | 'count' | 'rates' | 'top_n' | 'compact_history_hours' | 'worktree_markers'> & {
    context?: { growth_window_s: number }
    sections?: { running_s?: number }
    jauge?: { active_s?: number }
  },
  opts: { now: number; session?: string; cwd?: string; files?: number; ms?: number; price?: (e: Ev) => number; lib?: string },
): View => {
  const { now, session } = opts
  const price: Price = opts.price ?? cfg.rates
  const repoOf = (s: string) => sessions[s]?.repo ?? (sessions[s]?.cwd ? repoKey(sessions[s].cwd, cfg.worktree_markers) : undefined)
  const repo = opts.cwd ? repoKey(opts.cwd, cfg.worktree_markers) : session ? repoOf(session) : undefined
  const ctx: ScopeCtx = { session, repo, repoOf }
  const ids = SCOPES.filter(id => (session ? true : id === 'project' ? !!repo : id === 'all'))
  const longest = Math.max(...cfg.windows_s)
  const scopes = ids.map(id => {
    const evs = events.filter(e => inScope(id, e, ctx))
    return {
      id,
      rates: cfg.windows_s.map(w => rateOf(evs, now, w, cfg.count, price)),
      spark: spark(evs, now, cfg.spark_min, cfg.bucket_s, cfg.count),
    }
  })

  // hottest sessions over the longest window
  const bySession = new Map<string, Ev[]>()
  for (const e of events) {
    if (e.t <= now - longest * 1000 || e.t > now) continue
    const l = bySession.get(e.s) ?? []
    l.push(e)
    bySession.set(e.s, l)
  }
  const since = now - cfg.compact_history_hours * 3600000
  const compOf = (s: string) => (sessions[s]?.compactions ?? []).filter(c => c.t > since && !c.a)
  const top: TopRow[] = [...bySession.entries()]
    .map(([s, evs]) => {
      const r = rateOf(evs, now, longest, cfg.count, price)
      const m = sessions[s]
      const cs = compOf(s)
      return {
        s,
        title: titleOf(m, s),
        repo: repoName(repoOf(s) ?? '?'),
        tps: r.tps,
        usdPerH: r.usdPerH,
        ctx: m?.ctx,
        compactions: cs.length,
        lastCompact: cs.at(-1)?.t,
        last: m?.last ?? 0,
        isThis: s === session,
      }
    })
    .sort((a, b) => b.tps - a.tps)
    .slice(0, cfg.top_n)

  const byRepo = new Map<string, { evs: Ev[]; sessions: Set<string> }>()
  for (const [s, evs] of bySession) {
    const k = repoOf(s) ?? '?'
    const g = byRepo.get(k) ?? { evs: [], sessions: new Set() }
    g.evs.push(...evs)
    g.sessions.add(s)
    byRepo.set(k, g)
  }
  const projects = [...byRepo.entries()]
    .map(([k, g]) => {
      const r = rateOf(g.evs, now, longest, cfg.count, price)
      return { repo: repoName(k), tps: r.tps, usdPerH: r.usdPerH, sessions: g.sessions.size }
    })
    .sort((a, b) => b.tps - a.tps)

  const compactions: CompactRow[] = Object.values(sessions)
    .map(m => ({ s: m.s, title: titleOf(m, m.s), repo: repoName(repoOf(m.s) ?? '?'), isThis: m.s === session, items: compOf(m.s) }))
    .filter(r => r.items.length > 0)
    .sort((a, b) => Number(b.isThis) - Number(a.isThis) || (b.items.at(-1)?.t ?? 0) - (a.items.at(-1)?.t ?? 0))

  const marksFor = (pick: (s: string) => boolean) =>
    Object.values(sessions)
      .filter(m => pick(m.s))
      .flatMap(m => m.compactions.map(c => bucketOf(c.t, now, cfg.spark_min, cfg.bucket_s)))
      .filter(i => i >= 0)
  const me = session ? sessions[session] : undefined
  return {
    now,
    windows: cfg.windows_s,
    spark_min: cfg.spark_min,
    bucket_s: cfg.bucket_s,
    count: cfg.count,
    repo: repo ? repoName(repo) : undefined,
    scopes,
    top,
    projects,
    compactions,
    marks: {
      conv: marksFor(s => s === session),
      project: marksFor(s => !!repo && repoOf(s) === repo),
      all: marksFor(() => true),
    },
    conv: me
      ? {
          ctx: me.ctx,
          ctxT: me.ctxT,
          last: me.last,
          title: me.title,
          growthTpm: growthTpm(me.samples, now, cfg.context?.growth_window_s ?? 600),
          agents: agentsOf(events, session, now, cfg.sections?.running_s ?? 120),
          ...(me.pr ? { pr: me.pr } : {}),
        }
      : undefined,
    pc: pcActivity(events, now, cfg.sections?.running_s ?? 120, cfg.jauge?.active_s ?? 300),
    files: opts.files ?? 0,
    ms: opts.ms ?? 0,
    lib: opts.lib ?? 'band',
  }
}

// ---------- this conversation's context ----------

export type Ctx = {
  tokens?: number
  window: number
  usedPct?: number
  threshold: number
  thresholdPct: number
  thresholdSource: 'engine' | 'config'
  toCompact?: number
  toCompactPct?: number
  etaMin?: number
  relay: 'ok' | 'near' | 'over'
  level: 'ok' | 'warn' | 'bad'
  idleEtaMin?: number
  idleMin?: number
}

export const contextInfo = (
  a: { tokens?: number; window?: number; percent?: number; autoCompactThreshold?: number; growthTpm?: number; last?: number; now: number },
  c: Config['context'],
  idle: Config['idle_compact'],
): Ctx => {
  const window = a.window || c.window_fallback
  const fromEngine = typeof a.autoCompactThreshold === 'number' && a.autoCompactThreshold > 0
  const threshold = fromEngine ? (a.autoCompactThreshold as number) : Math.round((window * c.autocompact_pct_fallback) / 100)
  const t = a.tokens
  const usedPct = a.percent ?? (t !== undefined ? (t * 100) / window : undefined)
  const toCompact = t !== undefined ? Math.max(0, threshold - t) : undefined
  const etaMin = toCompact !== undefined && a.growthTpm && a.growthTpm > 0 ? toCompact / a.growthTpm : undefined
  const relay = t === undefined ? 'ok' : t >= c.handoff_tokens ? 'over' : t >= c.handoff_near_tokens ? 'near' : 'ok'
  const level = t === undefined ? 'ok' : t >= c.handoff_tokens ? 'bad' : t >= c.warn_tokens ? 'warn' : 'ok'
  const idleMin = a.last ? Math.max(0, (a.now - a.last) / 60000) : undefined
  const idleEtaMin = t !== undefined && t >= idle.min_tokens && idleMin !== undefined ? Math.max(0, idle.idle_min - idleMin) : undefined
  return {
    tokens: t,
    window,
    usedPct,
    threshold,
    thresholdPct: (threshold * 100) / window,
    thresholdSource: fromEngine ? 'engine' : 'config',
    toCompact,
    toCompactPct: toCompact !== undefined ? (toCompact * 100) / window : undefined,
    etaMin,
    relay,
    level,
    idleEtaMin,
    idleMin,
  }
}

// ---------- band text ----------

export type BandPart = { text: string; tone?: 'ok' | 'warn' | 'bad' | 'dim' }

const L = (labels: Record<string, string>, k: string) => labels[k] ?? k

export const bandParts = (
  view: View | undefined,
  ctx: Ctx | undefined,
  week: number | undefined,
  spec: { items: string[]; scopes: string[] },
  cfg: Pick<Config, 'labels' | 'band_window_s' | 'idle_compact'>,
): BandPart[] => {
  const lb = cfg.labels
  const out: BandPart[] = []
  for (const item of spec.items) {
    if (item === 'ctx' && ctx?.usedPct !== undefined) {
      out.push({ text: `${L(lb, 'ctx')} ${fmtPct(ctx.usedPct)} (${fmtTok(ctx.tokens ?? 0)})`, tone: ctx.level })
    } else if (item === 'compact' && ctx?.toCompactPct !== undefined) {
      const eta = ctx.etaMin !== undefined ? ` · ${L(lb, 'compact_in')} ~${Math.max(1, Math.round(ctx.etaMin))} min` : ''
      out.push({ text: `${L(lb, 'compact_at')} ${fmtPct(ctx.thresholdPct)} · ${L(lb, 'left')} ${fmtPct(ctx.toCompactPct)}${eta}`, tone: ctx.toCompactPct < 5 ? 'bad' : ctx.toCompactPct < 15 ? 'warn' : undefined })
    } else if (item === 'relay' && ctx && ctx.relay !== 'ok') {
      out.push({ text: L(lb, ctx.relay === 'over' ? 'relay_over' : 'relay_near'), tone: ctx.relay === 'over' ? 'bad' : 'warn' })
    } else if (item === 'idle' && ctx?.idleEtaMin !== undefined && (ctx.idleMin ?? 0) >= cfg.idle_compact.show_after_idle_min) {
      out.push({ text: `${L(lb, 'idle_compact_in')} ~${Math.round(ctx.idleEtaMin)} min`, tone: 'warn' })
    } else if (item === 'rates' && view) {
      for (const id of spec.scopes) {
        const row = view.scopes.find(r => r.id === id)
        if (!row) continue
        const r = row.rates.find(x => x.w === cfg.band_window_s) ?? row.rates[0]
        out.push({ text: `${L(lb, id)} ${fmtTok(r.tps)} tok/s` })
      }
    } else if (item === 'week' && week !== undefined) {
      out.push({ text: `${L(lb, 'week')} ${fmtPct(week)}`, tone: week >= 90 ? 'bad' : week >= 75 ? 'warn' : undefined })
    }
  }
  return out
}
export const bandText = (parts: BandPart[]) => parts.map(p => p.text).join(' · ')

// ---------- config ----------

const isObj = (x: unknown): x is Record<string, unknown> => !!x && typeof x === 'object' && !Array.isArray(x)
export const deepMerge = <T>(base: T, over: unknown): T => {
  if (!isObj(base) || !isObj(over)) return (over === undefined ? base : (over as T))
  const out: Record<string, unknown> = { ...base }
  for (const [k, v] of Object.entries(over)) {
    if (k.startsWith('_')) continue
    out[k] = isObj(v) && isObj(out[k]) ? deepMerge(out[k], v) : v
  }
  return out as T
}
export const expandHome = (p: string, home: string) => (p.startsWith('~') ? home.replace(/[\\/]+$/, '') + p.slice(1) : p)

export const compactLabel = (c: Compaction, labels: Record<string, string>, idleMin: number) => {
  if (c.trigger === 'manual') return L(labels, 'trigger_manual')
  if (c.trigger === 'auto' && (c.gapMin ?? 0) >= idleMin * 0.8) return L(labels, 'trigger_idle')
  if (c.trigger === 'auto') return L(labels, 'trigger_auto')
  return c.trigger === '?' ? L(labels, 'trigger_unknown') : c.trigger
}

// ---------- launcher (the Mods button bar) ----------

/** args: what the press passes to the command (« fil » opens /veille fil); key: the open-state id when two buttons share a mod. */
export type LauncherItem = { label: string; short?: string; mod: string; command: string; args?: string; key?: string }
/** preset hubs (default): items, the 6 hub entries; all: all_items, the 15 older buttons. */
export type Launcher = {
  enabled?: boolean
  close_args?: string
  preset?: string
  /** one hub open at a time */
  single?: boolean
  items?: LauncherItem[]
  /** shown when the band is unfolded (▾): Jauge, band's own detail pane */
  more_items?: LauncherItem[]
  all_items?: LauncherItem[]
}

/** The items of the chosen preset: all -> all_items (when listed), anything else -> items. */
export const launcherItems = (l: Launcher | undefined): LauncherItem[] =>
  !l ? [] : l.preset === 'all' && Array.isArray(l.all_items) && l.all_items.length ? l.all_items : (l.items ?? [])
/** The preset's items and the unfolded ones (more_items), for the open-state tracking. */
export const allLauncherItems = (l: Launcher | undefined): LauncherItem[] => [...launcherItems(l), ...(l && Array.isArray(l.more_items) ? l.more_items : [])]

/** single: the open buttons to close when `key` opens (every other open one), as items. */
export const othersOpen = (items: readonly LauncherItem[], open: readonly string[], key: string) =>
  items.filter((i, n) => i && launcherKey(i) !== key && open.includes(launcherKey(i)) && items.findIndex(j => launcherKey(j) === launcherKey(i)) === n)

/** One slash command as $.command.list() gives it (name, and the plugin that registered it when known). */
export type CommandSeen = { name: string; plugin?: string }
export type LauncherButton = LauncherItem & { loaded: boolean; open: boolean; hint?: string }
export type LauncherAction = { run: { command: string; args?: string }; open: boolean } | { toast: string }

/** A mod counts as loaded when its command is in this session and, where the engine names the plugin, it is that mod. */
export const isLoaded = (item: LauncherItem, commands: readonly CommandSeen[]) =>
  commands.some(c => c.name === item.command && (!c.plugin || c.plugin === item.mod || c.plugin.startsWith(`${item.mod}@`)))

/** The buttons to draw, in config order; empty when the launcher is off or lists nothing. */
export const launcherButtons = (
  l: Launcher | undefined,
  commands: readonly CommandSeen[],
  open: readonly string[],
  labels: Record<string, string>,
): LauncherButton[] => {
  if (!l || l.enabled === false) return []
  return launcherItems(l)
    .filter(i => i && i.label && i.mod && i.command)
    .map(i => {
      const loaded = isLoaded(i, commands)
      return {
        ...i,
        loaded,
        open: loaded && open.includes(launcherKey(i)),
        ...(loaded ? {} : { hint: (labels.launcher_missing ?? 'not loaded: add mods/{mod} to CLAUDE_CODE_PLUGIN_DIRS').replace('{mod}', i.mod) }),
      }
    })
}

/** What a press does: a mod not loaded explains itself; else open (/<command>) or, when open, close (/<command> <close_args>). */
export const launcherPress = (b: LauncherButton, closeArgs = 'close'): LauncherAction => {
  if (!b.loaded) return { toast: b.hint ?? b.mod }
  return b.open ? { run: { command: b.command, args: closeArgs }, open: false } : { run: { command: b.command, ...(b.args ? { args: b.args } : {}) }, open: true }
}

/** The open-state id of a button: its key, else its mod. */
export const launcherKey = (i: LauncherItem) => i.key || i.mod

/** What a typed /<command> <args> does to the buttons: closing closes every button of that command; else the button
 * whose args match opens (the one without args when none matches), and the other buttons of that command close. */
export const launcherTyped = (items: readonly LauncherItem[], command: string, args: string, closeArgs = 'close') => {
  const mine = items.filter(i => i && i.command === command)
  if (!mine.length) return null
  const a = (args ?? '').trim()
  if (a === closeArgs) return { open: [] as string[], close: mine.map(launcherKey) }
  const hit = mine.find(i => (i.args ?? '') && a.split(/\s+/)[0] === i.args) ?? mine.find(i => !i.args)
  return { open: hit ? [launcherKey(hit)] : [], close: mine.filter(i => i !== hit).map(launcherKey) }
}

/** The open list after a press on `mod`. */
export const toggleOpen = (open: readonly string[], mod: string, isOpen: boolean) =>
  isOpen ? (open.includes(mod) ? [...open] : [...open, mod]) : open.filter(m => m !== mod)

// ---------- hand-off helper (« Passation conseillée ») ----------

export type HandoffCfg = {
  enabled?: boolean
  /** the orange line under the band; false: only the pane's Passation block */
  band?: boolean
  /** context tokens of this conversation from which the line shows (the RESUME rule: 250 K) */
  threshold_tokens: number
  /** also show it when the forecast puts auto-compact within this many minutes */
  eta_min: number
  /** the slash command « Préparer RESUME » runs, without the slash, and its arguments */
  command: string
  args?: string
  /** RESUME files looked for, relative to the session's folder, then to its repo root; the first found wins */
  files: string[]
  history_n: number
  preview_chars: number
}

export type HandoffAdvice = { show: boolean; reasons: ('tokens' | 'eta')[] }

/** The line shows when the context reached threshold_tokens or the auto-compact forecast is within eta_min. */
export const handoffAdvice = (ctx: Ctx | undefined, h: HandoffCfg | undefined): HandoffAdvice => {
  if (!ctx || !h || h.enabled === false) return { show: false, reasons: [] }
  const reasons: HandoffAdvice['reasons'] = []
  if (ctx.tokens !== undefined && ctx.tokens >= h.threshold_tokens) reasons.push('tokens')
  if (ctx.etaMin !== undefined && h.eta_min > 0 && ctx.etaMin <= h.eta_min) reasons.push('eta')
  return { show: reasons.length > 0, reasons }
}

const fill = (s: string, vars: Record<string, string>) => s.replace(/\{(\w+)\}/g, (m, k: string) => vars[k] ?? m)

export const handoffReason = (a: HandoffAdvice, ctx: Ctx | undefined, h: HandoffCfg, labels: Record<string, string>) =>
  a.reasons
    .map(r =>
      r === 'tokens'
        ? fill(L(labels, 'handoff_reason_tokens'), { tokens: fmtTok(ctx?.tokens ?? 0), threshold: fmtTok(h.threshold_tokens) })
        : fill(L(labels, 'handoff_reason_eta'), { min: String(Math.max(1, Math.round(ctx?.etaMin ?? 0))) }),
    )
    .join(' · ')

/** "mis à jour il y a 3 h", or the absent label when there is no file. */
export const ageText = (mtime: number | undefined, now: number, labels: Record<string, string>) => {
  if (mtime === undefined) return L(labels, 'handoff_absent')
  const min = Math.max(0, (now - mtime) / 60000)
  const ago = min < 1 ? "à l'instant" : min < 60 ? `il y a ${Math.round(min)} min` : min < 48 * 60 ? `il y a ${Math.round(min / 60)} h` : `il y a ${Math.round(min / 1440)} j`
  return `${L(labels, 'handoff_updated')} ${ago}`
}

/** Where to look for RESUME: each file under the session's folder, then under its repo root (worktree markers cut). */
export const resumeCandidates = (cwd: string | undefined, files: string[], markers: string[]) => {
  if (!cwd) return []
  const here = norm(cwd)
  const repo = repoKey(cwd, markers)
  const dirs = repo && repo !== '?' && repo !== here ? [here, repo] : [here]
  return dirs.flatMap(d => files.map(f => `${d}/${f.replace(/\\/g, '/').replace(/^\/+/, '')}`))
}

export type HandoffButton = { key: 'handoff-prepare' | 'handoff-open'; label: string; enabled: boolean; hint?: string }

/** The two buttons. « Préparer » is greyed when the command is not in this session; « Ouvrir » always answers. */
export const handoffButtons = (h: HandoffCfg, commands: readonly CommandSeen[], resume: { path?: string; mtime?: number } | undefined, labels: Record<string, string>): HandoffButton[] => {
  const has = commands.some(c => c.name === h.command)
  return [
    {
      key: 'handoff-prepare',
      label: L(labels, 'handoff_prepare'),
      enabled: has,
      ...(has ? {} : { hint: fill(L(labels, 'handoff_missing'), { command: h.command }) }),
    },
    {
      key: 'handoff-open',
      label: L(labels, 'handoff_open'),
      enabled: true,
      ...(resume?.path && resume.mtime !== undefined ? {} : { hint: L(labels, 'handoff_absent') }),
    },
  ]
}

export type HandoffEvent = { t: number; kind: 'compact' | 'handoff' | 'resume'; text: string }

/** The last `n` hand-offs (/handoff runs, RESUME writes during this conversation) and compactions, newest first. */
export const recentHandoffs = (
  compactions: Compaction[],
  ran: number[],
  resume: { mtime?: number } | undefined,
  since: number | undefined,
  n: number,
  labels: Record<string, string>,
  idleMin: number,
): HandoffEvent[] => {
  const out: HandoffEvent[] = [
    ...compactions.filter(c => !c.a).map(c => ({
      t: c.t,
      kind: 'compact' as const,
      text: `${L(labels, 'handoff_compact')} ${compactLabel(c, labels, idleMin)}${c.pre ? ` ${fmtTok(c.pre)}→${fmtTok(c.post ?? 0)}` : ''}`,
    })),
    ...ran.map(t => ({ t, kind: 'handoff' as const, text: L(labels, 'handoff_ran') })),
  ]
  if (resume?.mtime !== undefined && (since === undefined || resume.mtime >= since)) out.push({ t: resume.mtime, kind: 'resume', text: L(labels, 'handoff_written') })
  return out.sort((a, b) => b.t - a.t).slice(0, Math.max(0, n))
}

